+
+function uniquePositive(list) {
+    var seen = {};
+    var out = [];
+    (list || []).forEach(function (h) {
+        var n = normalizeHolder(h);
+        if (n > 0 && !seen[n]) {
+            seen[n] = true;
+            out.push(n);
+        }
+    });
+    return out;
