    return {
        selfHealed: false,
        holders: live.slice(),
        alarm: null,
        mutexSelfHeals: 0,
        phantomHolderTicks: 0,
        consecutivePhantomTicks: 0
    };
}

function phantomAlarmOf(liveSnapshot, cachedSnapshot, cached, live) {
    return {
