function normalizeHolder(h) {
    if (h === null || h === undefined) return 0;
    if (typeof h === 'number') return Math.floor(h);
    if (typeof h === 'string') {
        var n = parseInt(h, 10);
        return isNaN(n) ? 0 : n;
    }
    if (typeof h === 'object') return holderFromObject(h);
    return 0;
