    return merged.filter(function (n) {
        if (!labelSet[n]) {
            if (candSet[n]) phantoms.push(n);
            return false;
        }
        if (concluded(n)) {
            // label still on, run concluded → the label layer does not
            // confirm; it is a phantom source, not a holder
            if (candSet[n]) phantoms.push(n);
