            { name: 'kicker / head-completeness', conclusion: 'cancelled', status: 'completed' }
        ] };
    }

    function kickerJobs() {
        return { 555001: [
            { name: 'kicker / sm-liveness' }, { name: 'kicker / head-completeness' }
        ] };
    }

