        var mod = loadBare();
        var provider = { listOpenPrsLive: function () { throw new Error('boom'); } };
        var out = mod.rederiveHoldersLive([97], [pr(97, ['ai_validating'])], provider,
            { owner: 'o', repo: 'r' }, { mutex: 'ai_validating' });
        assert.deepEqual(out, [97]);
    });

