            }
            var m = /runs\/(\d+)\/jobs/.exec(c);
            if (m) {
                return JSON.stringify({ jobs: (opts.jobsByRun || {})[m[1]] || [] });
            }
            return '';
        };
    }

    function paramsAny() {
        return { jobParams: { owner: 'IstiN', repo: 'flutter_agent_harness',
