            ] },
            { headRuns: [
                { id: 555002, status: 'completed', conclusion: 'cancelled',
                  head_sha: '755abc', run_attempt: 1,
                  created_at: '2026-10-05T10:00:01Z', updated_at: '2026-10-05T10:00:03Z' }
            ],
              jobsByRun: { 555002: [{ name: 'docs-freshness' }] } });
