Implementation:
```js
function recordSilentUpdateFailure(key, ticket) {
   try {
       var tracker = githubTracker(effectiveRepoInfo.owner, effectiveRepoInfo.repo);
       var comments = tracker.getComments(ticket.prNumber) || [];
       var count = validationLivenessModule.silentUpdateFailureCount(coments);
       var attempt = count.count + 1;
       var iso = new Date().toISOString();
       var left = validationLivenessModule.silentUpdateAttemptsLeft(attempt);
       if (left > 0) {
           tracker.postComment(ticket.prNumber,
               validationLivenessModule.silentUpdateFailureLine(attempt, iso));
           console.warn(' ⚠️ ' + key + ' silent-update failure #' + attempt +
               ' recorded — ' + left + ' attempt(s) left before degraded flag (I5)');
           return;
       }
       // attempts exhausted — flag the PR once (visible state); marker
       // already at MAX, no comment spam beyond it.
       if ((ticket.labels || []).indexOf(validationLivenessModule.SILENT_UPDATE_DEGRADED_LABEL) === -1) {
           tracker.addLabel(ticket.prNumber, validationLivenessModule.SILENT_UPDATE_DEGRADED_LABEL);
       }
       console.error(' ❌ ' + key + ' silent-update degraded after ' +
           validationLivenessModule.SILENT_UPDATE_MAX_FAILURES +
           ' consecutive clone failures — flagged silent-update-degraded (I5)');
   } catch (eI5) {
       console.warn(' ⚠️ ' + key + ' I5 failure bookkeeping failed: ' + (eI5.message || eI5));
   }
```

